spec={'records':{},'waves':[]}
for level,(theme,opening,larva,peaks,raw) in DATA.items():
    rows=[line.split()for line in raw.split(';')];assert len(rows)==25
    for wave,(gap,clear,hp,speed) in enumerate(rows,1):
        enemies={}
        if wave<=4:
            enemies={'Chick':{'hp':opening[wave-1],'speed':1.10,'reward':2},'Chicken':{'hp':opening[wave-1],'speed':1.10,'reward':2}}
            if wave in (3,4):enemies['Larva']={'hp':larva[wave-3]}
        if float(hp)>0:enemies['@air']={'hp':float(hp),'speed':float(speed)}
        reason=theme+'；'+('本关主要压力窗，密度与速度共同压缩投资容错' if wave in peaks else '独立维护本波密度与清波资金，保留已审计的怪物数、出场顺序及未列属性')
        spec['waves'].append(dict(level=level,wave=wave,gap=int(gap),clear=int(clear),enemies=enemies,reason=reason))
path=REPORT/'design-L07-L12-r1.json';path.write_text(json.dumps(spec,ensure_ascii=False,indent=2),encoding='utf-8');manifest(path)
